	parent := writer.StartTable(6)
	writer.SetUint8(0, f.Class)
	writer.SetUint8(1, f.Default)
	writer.SetUint8(2, f.In)
	writer.SetUint8(3, f.Match)
	writer.SetUint8(4, f.Self)
