// StructsFields are the fields of a [Structs], to write.
type StructsFields struct {
	// A struct of every scalar type
	Packed Packed
	// An array of structs of 7 bytes, aligned to 4
	Documented []Documented
	// A struct of structs
	Segment  Segment
	Segments []Segment
	// A table nested in the message, which holds structs too
	Path PathFields
}

// MarshalBinary writes a [Structs] with every field. It fails with a
// [*tafla.BuildError] if it's longer than its offset type, uint32, addresses.
func (f StructsFields) MarshalBinary() ([]byte, error) {
	return f.AppendBinary(nil)
}

// AppendBinary appends a [Structs] with every field to bytes, as
// [StructsFields.MarshalBinary] writes it, and returns the extended bytes, into
// their capacity when they have room. It fails as MarshalBinary does.
func (f StructsFields) AppendBinary(bytes []byte) ([]byte, error) {
	sizer, err := tafla.NewTableSizer(5, Structs{}.layout())
	if err != nil {
		return nil, err
	}
	sizer.AddStruct(43)
	sizer.AddStructArray(len(f.Documented), 7, tafla.Align4)
	sizer.AddStruct(16)
	sizer.AddStructArray(len(f.Segments), 16, tafla.Align4)
	sizer.AddTable(tafla.Align4)
	f.Path.size(&sizer)

	writer, err := sizer.AppendWriter(bytes)
	if err != nil {
		return nil, err
	}
	f.Packed.put(writer.ReserveStruct(0, 43))
	structs := writer.ReserveStructArray(1, len(f.Documented), 7, tafla.Align4)
	for item := range f.Documented {
		f.Documented[item].put(structs[item*7:])
	}
	f.Segment.put(writer.ReserveStruct(2, 16))
	structs = writer.ReserveStructArray(3, len(f.Segments), 16, tafla.Align4)
	for item := range f.Segments {
		f.Segments[item].put(structs[item*16:])
	}
	writer.SetTable(4, tafla.Align4)
	f.Path.write(&writer)

	return writer.Bytes()
}

